messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Treadmill Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background: #222; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);
    scene.fog = new THREE.Fog(0x222222, 10, 25);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 2.5, 8);
    camera.lookAt(0, 1.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffddaa, 1.2);
    dirLight.position.set(-5, 5, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 20;
    scene.add(dirLight);

    // --- Materials ---
    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, flatShading: true });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366ff, flatShading: true });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x222222, flatShading: true });

    // --- Helper: Create Low Poly Mesh ---
    function createLimb(geometry, material, position = [0,0,0], rotation = [0,0,0]) {
        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.set(...position);
        mesh.rotation.set(...rotation);
        mesh.castShadow = true;
        return mesh;
    }

    // --- Treadmill ---
    const treadmillGroup = new THREE.Group();
    scene.add(treadmillGroup);

    // Floor
    const floorGeo = new THREE.BoxGeometry(10, 0.1, 4);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
    const floor = createLimb(floorGeo, floorMat, [0, -0.05, 0]);
    floor.receiveShadow = true;
    treadmillGroup.add(floor);

    // Belt
    const beltGeo = new THREE.BoxGeometry(3, 0.05, 2.8);
    const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
    const belt = createLimb(beltGeo, beltMat, [0, 0.02, 0]);
    treadmillGroup.add(belt);

    // Rails
    const railGeo = new THREE.BoxGeometry(3.2, 0.05, 0.2);
    const railMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
    const railLeft = createLimb(railGeo, railMat, [0, 0.02, -1.3]);
    const railRight = createLimb(railGeo, railMat, [0, 0.02, 1.3]);
    treadmillGroup.add(railLeft, railRight);

    // --- Humanoid ---
    const humanGroup = new THREE.Group();
    scene.add(humanGroup);

    // Torso
    const torsoGeo = new THREE.BoxGeometry(0.6, 0.8, 0.4);
    const torso = createLimb(torsoGeo, shirtMat, [0, 1.6, 0]);
    humanGroup.add(torso);

    // Head
    const headGeo = new THREE.BoxGeometry(0.35, 0.35, 0.35);
    const head = createLimb(headGeo, skinMat, [0.1, 2.15, 0]);
    humanGroup.add(head);

    // Arms
    const armGeo = new THREE.BoxGeometry(0.2, 0.6, 0.2);
    const handGeo = new THREE.BoxGeometry(0.15, 0.15, 0.15);

    const leftArmPivot = new THREE.Group();
    leftArmPivot.position.set(0, 1.95, 0);
    const leftArm = createLimb(armGeo, skinMat, [0, -0.3, 0]);
    const leftHand = createLimb(handGeo, skinMat, [0, -0.65, 0]);
    leftArmPivot.add(leftArm, leftHand);
    humanGroup.add(leftArmPivot);

    const rightArmPivot = new THREE.Group();
    rightArmPivot.position.set(0, 1.95, 0);
    const rightArm = createLimb(armGeo, skinMat, [0, -0.3, 0]);
    const rightHand = createLimb(handGeo, skinMat, [0, -0.65, 0]);
    rightArmPivot.add(rightArm, rightHand);
    humanGroup.add(rightArmPivot);

    // Legs
    const legGeo = new THREE.BoxGeometry(0.25, 0.7, 0.25);
    const footGeo = new THREE.BoxGeometry(0.25, 0.1, 0.35);

    const leftLegPivot = new THREE.Group();
    leftLegPivot.position.set(0, 1.2, 0);
    const leftLeg = createLimb(legGeo, pantsMat, [0, -0.35, 0]);
    const leftFoot = createLimb(footGeo, skinMat, [0.05, -0.75, 0]);
    leftLegPivot.add(leftLeg, leftFoot);
    humanGroup.add(leftLegPivot);

    const rightLegPivot = new THREE.Group();
    rightLegPivot.position.set(0, 1.2, 0);
    const rightLeg = createLimb(legGeo, pantsMat, [0, -0.35, 0]);
    const rightFoot = createLimb(footGeo, skinMat, [0.05, -0.75, 0]);
    rightLegPivot.add(rightLeg, rightFoot);
    humanGroup.add(rightLegPivot);

    // --- Animation State ---
    const CYCLE_DURATION = 10;
    let time = 0;

    function animate() {
        requestAnimationFrame(animate);

        const now = performance.now() / 1000;
        time = (now % CYCLE_DURATION);

        // State: 0-2 Idle, 2-5 Walk, 5-8 Run, 8-10 Idle
        // Phase: 0-0.2 Idle, 0.2-0.5 Walk, 0.5-0.8 Run, 0.8-1.0 Idle

        let state = 'idle';
        let swingPhase = 0;
        let speed = 0;
        let amplitude = 0;
        let lean = 0;
        let bounce = 0;
        let armBend = 0;

        if (time < 2) {
            state = 'idle';
        } else if (time < 5) {
            state = 'walk';
            const t = (time - 2) / 3;
            speed = 2;
            amplitude = 0.4;
            lean = 0;
            bounce = 0.02;
            armBend = 0;
            swingPhase = t * Math.PI * 2;
        } else if (time < 8) {
            state = 'run';
            const t = (time - 5) / 3;
            speed = 4.5;
            amplitude = 0.7;
            lean = 0.2;
            bounce = 0.05;
            armBend = 0.4;
            swingPhase = t * Math.PI * 2;
        } else {
            state = 'idle';
        }

        // Smooth transitions for pose
        // We use a simple sine wave for limb swing, but interpolate amplitude/lean based on state duration
        // To make it look natural, we calculate the target pose and lerp, but for a strict cycle, 
        // direct calculation with smooth start/end envelopes is better.

        // Envelope for walk/run to start/end smoothly from idle
        let envelope = 0;
        if (state === 'walk') {
            const t = (time - 2) / 3;
            envelope = Math.sin(t * Math.PI); // Start and end at 0
        } else if (state === 'run') {
            const t = (time - 5) / 3;
            envelope = Math.sin(t * Math.PI);
        } else {
            envelope = 0;
        }

        // Calculate limb angles
        // Left leg leads, right leg follows
        const leftAngle = Math.sin(swingPhase * speed) * amplitude * envelope;
        const rightAngle = Math.sin(swingPhase * speed + Math.PI) * amplitude * envelope;

        // Arms opposite to legs
        const leftArmAngle = Math.sin(swingPhase * speed + Math.PI) * (amplitude * 0.8) * envelope;
        const rightArmAngle = Math.sin(swingPhase * speed) * (amplitude * 0.8) * envelope;

        // Apply poses
        humanGroup.position.y = bounce * envelope;
        humanGroup.rotation.z = lean * envelope;

        leftLegPivot.rotation.x = leftAngle;
        rightLegPivot.rotation.x = rightAngle;

        // Arm pivots are at shoulder. We rotate the whole arm group.
        // To make elbows bend, we could add elbow joints, but simple box arms can just rotate forward/back.
        // Adding a slight extra rotation for running to simulate bend/extension
        const armExtension = armBend * envelope * Math.sin(swingPhase * speed);

        leftArmPivot.rotation.x = leftArmAngle - armExtension;
        rightArmPivot.rotation.x = rightArmAngle + armExtension;

        // Belt rotation visual
        belt.rotation.y = now * 2;

        renderer.render(scene, camera);
    }

    animate();

    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });
</script>
</body>
</html>
```
